@Composable fun NativeMailboxScreen(api:ApiClient,onExpired:()->Unit){var folder by rememberSaveable{mutableStateOf("inbox")};var query by rememberSaveable{mutableStateOf("")};var page by rememberSaveable(folder,query){mutableIntStateOf(1)};var id by rememberSaveable{mutableStateOf("")};var revision by remember{mutableIntStateOf(0)};var compose by remember{mutableStateOf<JSONObject?>(null)};var actionError by remember{mutableStateOf<String?>(null)};var selected by remember{mutableStateOf(setOf<Long>())};val scope=rememberCoroutineScope();androidx.activity.compose.BackHandler(id.isNotBlank()){id="";revision++}
    fun act(action:String,ids:List<Long>){scope.launch{try{api.post("workspace/mailbox.php",JSONObject().put("action",action).put("ids",JSONArray(ids)));revision++;selected=emptySet()}catch(c:CancellationException){throw c}catch(f:Exception){if(f is ApiException&&f.status==401)onExpired()else actionError=f.message}}}
    Column{
        if(!api.can("view_messages")){Column(Modifier.padding(20.dp)){PageTitle("Messages","Send campus messages with your current permission.");if(api.can("send_messages"))Button(onClick={compose=JSONObject()}){Text("Compose")};if(revision>0)Text("Message sent.")}}
        else if(id.isNotBlank()){
            TextButton(onClick={id="";revision++}){Text("Back to mailbox")}
            RemotePanel(api,"workspace/mailbox.php?id=$id&revision=$revision",onExpired){json->val message=json.getJSONObject("message");LazyColumn(contentPadding=pagePadding,verticalArrangement=Arrangement.spacedBy(12.dp)){
                item{PageTitle(message.text("subject"),"${message.text("sender_name")} · ${message.text("sent_at_display")}")}
                item{Text((message.optJSONArray("targets")?:JSONArray()).objects().joinToString("\n"){"${it.text("kind").uppercase()}: ${it.text("label")}"},style=MaterialTheme.typography.bodySmall)}
                item{val html=message.text("body_html");if(html.isBlank())Text(message.text("body"))else{val color=MaterialTheme.colorScheme.onSurface;AndroidView(factory={android.widget.TextView(it)},update={view->view.text=android.text.Html.fromHtml(html,android.text.Html.FROM_HTML_MODE_COMPACT);view.setTextColor(android.graphics.Color.argb((color.alpha*255).toInt(),(color.red*255).toInt(),(color.green*255).toInt(),(color.blue*255).toInt()));view.textSize=16f;view.movementMethod=android.text.method.LinkMovementMethod.getInstance()})}}
                items((message.optJSONArray("attachments")?:JSONArray()).objects()){file->AttachmentSave(api,file,onExpired)}
                if(message.optBoolean("can_manage"))item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){TextButton(onClick={act(if(message.text("starred_at").isBlank())"star"else"unstar",listOf(id.toLong()))}){Text(if(message.text("starred_at").isBlank())"Star"else"Unstar")};TextButton(onClick={act(if(message.text("read_at").isBlank())"read"else"unread",listOf(id.toLong()))}){Text(if(message.text("read_at").isBlank())"Mark read"else"Mark unread")};TextButton(onClick={act(if(message.text("deleted_at").isBlank())"trash"else"restore",listOf(id.toLong()))}){Text(if(message.text("deleted_at").isBlank())"Move to Trash"else"Restore")}}}
                if(api.can("send_messages"))item{Row{Button(onClick={compose=JSONObject().put("subject","Re: ${message.text("subject")}").put("body","\n\n${message.text("sent_at_display")} · ${message.text("sender_name")}\n${message.text("body")}").put("recipients",JSONArray().put(JSONObject().put("kind","to").put("type","user").put("id",message.optLong("sender_id")).put("label",message.text("sender_name"))))}){Text("Reply")};TextButton(onClick={compose=JSONObject().put("subject","Fwd: ${message.text("subject")}").put("body","${message.text("sent_at_display")} · ${message.text("sender_name")}\n${message.text("body")}").put("forward_attachment_ids",JSONArray((message.optJSONArray("attachments")?:JSONArray()).objects().map{it.optLong("id")}))}){Text("Forward")}}}
                actionError?.let{item{Text(it,color=MaterialTheme.colorScheme.error)}}
            }}
        }else RemotePanel(api,"workspace/mailbox.php?folder=$folder&q=${encoded(query)}&page=$page&revision=$revision",onExpired){json->LazyColumn(contentPadding=pagePadding,verticalArrangement=Arrangement.spacedBy(12.dp)){
            item{PageTitle("Messages","Your own mailbox, synchronized with the web.");if(api.can("send_messages"))Button(onClick={compose=JSONObject()}){Text("Compose")}}
            item{SearchSelect("Mailbox",folder,listOf("inbox" to "Inbox","starred" to "Starred","sent" to "Sent","trash" to "Trash")){folder=it;selected=emptySet()};OutlinedTextField(query,{query=it},label={Text("Search messages")},singleLine=true,modifier=Modifier.fillMaxWidth())}
            if(folder!="sent")item{Row{TextButton(onClick={act("read",selected.toList())},enabled=selected.isNotEmpty()){Text("Mark read (${selected.size})")};TextButton(onClick={act(if(folder=="trash")"restore"else"trash",selected.toList())},enabled=selected.isNotEmpty()){Text(if(folder=="trash")"Restore"else"Trash")}}}
            items((json.optJSONArray("items")?:JSONArray()).objects(),key={it.text("id")}){row->Card(onClick={id=row.text("id")},modifier=Modifier.fillMaxWidth()){Row(Modifier.padding(14.dp)){if(folder!="sent")Checkbox(row.optLong("id") in selected,{checked->selected=if(checked&&selected.size<100)selected+row.optLong("id")else selected-row.optLong("id")});Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(5.dp)){Text(row.text("subject"),style=if(row.text("read_at").isBlank())MaterialTheme.typography.titleMedium else MaterialTheme.typography.bodyLarge);Text(row.text("sender_name"));Text(row.text("preview"),maxLines=2);Text(row.text("sent_at_display"),style=MaterialTheme.typography.labelSmall);if(row.optInt("attachment_count")>0)Text("${row.optInt("attachment_count")} attachments",style=MaterialTheme.typography.labelSmall)}}}}
            if(json.optInt("total")==0)item{EmptyState("No matching messages","Try another folder or search.")}
            item{PageControls(page,json.optInt("pages",1),json.optInt("total")){page=it}}
            actionError?.let{item{Text(it,color=MaterialTheme.colorScheme.error)}}
        }}
    }
    compose?.let{draft->NativeComposer(api,draft,onExpired,{compose=null}){compose=null;revision++;folder="sent";id=""}}
}

@Composable private fun AttachmentSave(api:ApiClient,file:JSONObject,onExpired:()->Unit){var savedUri by remember{mutableStateOf<android.net.Uri?>(null)};var preview by remember{mutableStateOf(false)};if(preview)PrivateAttachmentPreview(api,file,onExpired){preview=false};if(file.text("mime_type").startsWith("image/"))TextButton(onClick={preview=true}){Text("Preview image")};val context=LocalContext.current;val scope=rememberCoroutineScope();var error by remember{mutableStateOf<String?>(null)};var busy by remember{mutableStateOf(false)};val save=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument(file.text("mime_type").ifBlank{"application/octet-stream"})){uri->if(uri!=null)scope.launch{busy=true;error=null;try{api.saveDocument(context.contentResolver,uri,"workspace/attachment.php?id=${file.text("id")}");savedUri=uri}catch(c:CancellationException){throw c}catch(f:Exception){if(f is ApiException&&f.status==401)onExpired()else error=f.message}finally{busy=false}}};OutlinedButton(onClick={save.launch(file.text("original_name").ifBlank{file.text("name")})},enabled=!busy){Text(if(busy)"Saving…"else"Save ${file.text("original_name").ifBlank{file.text("name")}}")};savedUri?.let{uri->TextButton(onClick={try{context.startActivity(android.content.Intent(android.content.Intent.ACTION_VIEW).setDataAndType(uri,file.text("mime_type").ifBlank{"application/octet-stream"}).addFlags(android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION))}catch(_:android.content.ActivityNotFoundException){error="No installed app can open this file. It remains saved in your selected location."}}){Text("Open saved file")}};error?.let{Text(it,color=MaterialTheme.colorScheme.error)}}

@OptIn(ExperimentalMaterial3Api::class)
@Composable private fun NativeComposer(api:ApiClient,draft:JSONObject,onExpired:()->Unit,close:()->Unit,sent:()->Unit){var announcement by remember{mutableStateOf(false)};var formatting by remember{mutableStateOf("plain")};var subject by remember{mutableStateOf(draft.text("subject"))};var bodyValue by remember{mutableStateOf(androidx.compose.ui.text.input.TextFieldValue(draft.text("body")))};val body=bodyValue.text;var formatTools by remember{mutableStateOf(false)};var linkEditor by remember{mutableStateOf(false)};var showPreview by remember{mutableStateOf(false)};var limits by remember{mutableStateOf<JSONObject?>(null)};var targets by remember{mutableStateOf((draft.optJSONArray("recipients")?:JSONArray()).objects())};var recipient by remember{mutableStateOf(false)};var kind by remember{mutableStateOf("to")};var busy by remember{mutableStateOf(false)};var error by remember{mutableStateOf<String?>(null)};var files by remember{mutableStateOf(listOf<UploadFile>())};val context=LocalContext.current;val scope=rememberCoroutineScope()
    LaunchedEffect(api){try{limits=api.get("workspace/mailbox.php?mode=limits").optJSONObject("limits")}catch(f:Exception){error=f.message}}
    fun wrap(prefix:String,suffix:String){val selection=bodyValue.selection;val start=minOf(selection.start,selection.end);val end=maxOf(selection.start,selection.end);val selected=body.substring(start,end).ifBlank{"Text"};bodyValue=androidx.compose.ui.text.input.TextFieldValue(body.replaceRange(start,end,prefix+selected+suffix),androidx.compose.ui.text.TextRange(start+prefix.length,start+prefix.length+selected.length))}
    val pick=rememberLauncherForActivityResult(ActivityResultContracts.OpenMultipleDocuments()){uris->scope.launch{try{val additions=withContext(Dispatchers.IO){uris.map{uri->var name="Attachment";context.contentResolver.query(uri,arrayOf(OpenableColumns.DISPLAY_NAME),null,null,null)?.use{c->if(c.moveToFirst())name=c.getString(0)};val bytes=context.contentResolver.openInputStream(uri)?.use{it.readLimited((limits?.optInt("file")?:5_242_880)+1)}?:error("Could not read the attachment.");require(bytes.size<=(limits?.optInt("file")?:5_242_880)){"Choose attachments up to 5 MB."};UploadFile(name,context.contentResolver.getType(uri)?:"application/octet-stream",bytes)}};require(files.size+additions.size+(draft.optJSONArray("forward_attachment_ids")?.length()?:0)<=(limits?.optInt("count")?:10)&&files.sumOf{it.bytes.size}+additions.sumOf{it.bytes.size}<=(limits?.optInt("total")?:20_971_520)){"Choose up to ten attachments, 20 MB in total."};files=files+additions}catch(f:Exception){error=f.message}}}
    Dialog(onDismissRequest={if(!busy)close()},properties=DialogProperties(usePlatformDefaultWidth=false)){Surface(Modifier.fillMaxSize()){Scaffold(topBar={TopAppBar(title={Text("Compose message")},navigationIcon={TextButton(onClick=close,enabled=!busy){Text("Cancel")}})},bottomBar={Column(Modifier.padding(16.dp)){error?.let{Text(it,color=MaterialTheme.colorScheme.error)};Button(enabled=!busy&&subject.isNotBlank()&&body.isNotBlank()&&targets.any{it.text("kind")=="to"},onClick={scope.launch{busy=true;error=null;try{val payload=JSONObject().put("subject",subject).put("body",body).put("body_html",formattedMessage(body,formatting)).put("is_announcement",if(announcement)"1"else"0").put("recipients_json",JSONArray(targets).toString()).put("forward_attachment_ids",(draft.optJSONArray("forward_attachment_ids")?:JSONArray()).toString());api.upload("workspace/send-message.php",payload,files);sent()}catch(c:CancellationException){throw c}catch(f:Exception){if(f is ApiException&&f.status==401)onExpired()else error=f.message}finally{busy=false}}},modifier=Modifier.fillMaxWidth()){Text(if(busy)"Sending…"else"Send message")}}}){padding->LazyColumn(Modifier.padding(padding),contentPadding=pagePadding,verticalArrangement=Arrangement.spacedBy(12.dp)){
        item{Row{OutlinedButton(onClick={kind="to";recipient=true}){Text("Add To")};TextButton(onClick={kind="cc";recipient=true}){Text("Add CC")}}}
        items(targets){target->Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("${target.text("kind").uppercase()}: ${target.text("label")}",modifier=Modifier.weight(1f));TextButton(onClick={targets=targets-target}){Text("Remove")}}}
        item{TextButton(onClick={formatTools=!formatTools}){Text("Formatting")};if(formatTools)Row{TextButton(onClick={wrap("**","**")}){Text("Bold")};TextButton(onClick={wrap("_","_")}){Text("Italic")};TextButton(onClick={wrap("__","__")}){Text("Underline")};TextButton(onClick={linkEditor=true}){Text("Link")}};TextButton(onClick={showPreview=!showPreview},enabled=body.isNotBlank()){Text(if(showPreview)"Hide preview"else"Preview message")};if(showPreview)Text(android.text.Html.fromHtml(formattedMessage(body,formatting),android.text.Html.FROM_HTML_MODE_COMPACT).toString());SearchSelect("Message style",formatting,listOf("plain" to "Paragraphs","bold" to "Bold paragraphs","list" to "Bullet list")){formatting=it};Row{Checkbox(announcement,{announcement=it});Text("Campus announcement",Modifier.padding(vertical=12.dp))};OutlinedTextField(subject,{subject=it},label={Text("Subject")},modifier=Modifier.fillMaxWidth(),singleLine=true);OutlinedTextField(bodyValue,{bodyValue=it},label={Text("Message")},supportingText={Text("Formatting: **bold**, _italic_, __underline__, [label](https://link). Text is safely rendered.")},modifier=Modifier.fillMaxWidth(),minLines=8)}
        item{OutlinedButton(onClick={pick.launch(arrayOf("*/*"))},enabled=!busy&&limits!=null){Text("Attach files")};Text("Up to ${limits?.optInt("count")?:10} files, ${(limits?.optInt("file")?:5_242_880)/1_048_576} MB each. Forwarded attachments retain server authorization.",style=MaterialTheme.typography.bodySmall)}
        items(files){file->Row{Text(file.name,Modifier.weight(1f));TextButton(onClick={files=files-file}){Text("Remove")}}}
    }}}}
    if(linkEditor)NativeEditor("Insert link",listOf(NativeField("label","Link label","Link",required=true),NativeField("url","Website URL",required=true)),onExpired,{linkEditor=false},"Insert"){input->require(input.text("url").startsWith("https://")||input.text("url").startsWith("http://")){"Enter a website URL beginning with https:// or http://."};val selection=bodyValue.selection;val start=minOf(selection.start,selection.end);val end=maxOf(selection.start,selection.end);val link="[${input.text("label")}](${input.text("url")})";bodyValue=androidx.compose.ui.text.input.TextFieldValue(body.replaceRange(start,end,link),androidx.compose.ui.text.TextRange(start+link.length))}
    if(recipient)RecipientPicker(api,kind,onExpired,{recipient=false}){targets=(targets+it).distinctBy{row->"${row.text("kind")}:${row.text("type")}:${row.text("id")}"};recipient=false}
}

@Composable private fun RecipientPicker(api:ApiClient,kind:String,onExpired:()->Unit,close:()->Unit,selected:(JSONObject)->Unit){var query by remember{mutableStateOf("")};var type by remember{mutableStateOf("user")};AlertDialog(onDismissRequest=close,title={Text("Add ${kind.uppercase()} recipient")},text={Column{SearchSelect("Recipient type",type,listOf("user" to "Person","section" to "Section","role" to "Role","all" to "All active users")){type=it};if(type=="user")OutlinedTextField(query,{query=it},label={Text("Search name or school ID")},singleLine=true);RemotePanel(api,"workspace/mailbox.php?mode=recipients&q=${encoded(query)}",onExpired){json->val options=when(type){"role"->json.optJSONArray("roles");"section"->json.optJSONArray("sections");else->json.optJSONArray("people")};LazyColumn(Modifier.heightIn(max=300.dp)){if(type=="all")item{TextButton(onClick={selected(JSONObject().put("kind",kind).put("type","all").put("label","All active users"))}){Text("All active users")}}else items((options?:JSONArray()).objects()){row->val label=row.text("name").ifBlank{row.text("label")};TextButton(onClick={selected(JSONObject().put("kind",kind).put("type",type).put("id",row.optLong("id")).put("label",label))}){Text(label)}}}}}},confirmButton={TextButton(onClick=close){Text("Close")}})}

internal fun formattedMessage(body:String,formatting:String)=messageHtml(body,formatting)
